import React from 'react';import {createRoot} from 'react-dom/client';import {ModuleHostProvider} from '@zq/module-api';import {useChat} from '../../../../modules/chat/useChat';import {ArtifactWorkspace} from '../../../../modules/chat/ArtifactPane';import ChatMarkdown from '../../../../modules/chat/ChatMarkdown';import '@zq/ui/styles.css';import '../../../../modules/chat/chat.css';import '../../src/shell.css';
const sources=Array.from({length:29},(_,i)=>({id:String(i+1),url:`https://example.com/article/${i+1}`,title:`Research article ${i+1}`}));
const message={id:'response',role:'assistant',content:'A claim with a source [1](https://example.com/article/1). A later reference [[29]](https://example.com/article/29). An ordinary [external link](https://other.example/) stays a link.',thinking:'',status:'complete',sources,createdAt:1,error:''};
const snapshot={revision:1,projects:[],connections:[],defaultModel:null,conversations:[{id:'chat',title:'Citation check',messages:[message]},{id:'other',title:'Other chat',messages:[]}],chatView:{selected:'chat',projectId:null,projectHome:false,positions:{}},drafts:{}};
let subscriber;
const ok=value=>Promise.resolve({ok:true,value});window.events=[];
const host={workspace:{layout:{view:'Chat'}},closing:false,registerFlush:()=>()=>{},commands:{register:()=>()=>{},run:()=>true},navigate:()=>{},notify:m=>window.events.push(['notify',m]),services:{chat:{load:()=>ok(snapshot),subscribe:fn=>{subscriber=fn;return()=>{}},createConversation:()=>new Promise(resolve=>{window.finishNewChat=()=>{const c={id:'new-chat',title:'New chat',messages:[]};snapshot.conversations.push(c);snapshot.revision++;subscriber({...snapshot});resolve({ok:true,value:c})}}),saveDraft:()=>ok(null),saveChatView:()=>ok(null),openLink:url=>{window.events.push(['open',url]);return ok(null)},sourceIcon:()=>ok(null)},voice:{},clipboard:{writeText:text=>{window.events.push(['copy',text]);return ok(null)}}}};
function Test(){const chat=useChat();return <div style={{height:'720px'}}><ArtifactWorkspace chat={chat}><div style={{padding:'40px'}}><button onClick={()=>chat.select('chat')}>Original chat</button><button onClick={()=>chat.select('other')}>Switch chat</button><button onClick={()=>void chat.create()}>New chat</button><button onClick={()=>chat.openProject(null)}>All chats</button><button onClick={()=>chat.openArtifacts()}>Artifacts</button><output aria-label="Current chat">{chat.conversation?.id}</output>{chat.conversation?.id==='chat'&&<ChatMarkdown content={message.content} sources={sources} onSourceOpen={(source,origin)=>chat.openSources('chat',message,source.url,origin)}/>}<textarea aria-label="Chat message" value={chat.drafts.chat??''} onChange={e=>chat.setDraft('chat',e.target.value)}/></div></ArtifactWorkspace></div>}
createRoot(document.getElementById('root')).render(<ModuleHostProvider value={host}><Test/></ModuleHostProvider>);
